    20→package org.apache.druid.guice;
    21→
    22→import com.fasterxml.jackson.annotation.JacksonInject;
    23→import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
    24→import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
    25→import com.fasterxml.jackson.databind.introspect.NopAnnotationIntrospector;
    26→import com.google.inject.BindingAnnotation;
    27→import com.google.inject.Key;
    28→import org.apache.druid.java.util.common.IAE;
    29→
    30→import java.lang.annotation.Annotation;
    31→
    32→/**
    33→ */
    34→public class GuiceAnnotationIntrospector extends NopAnnotationIntrospector
    35→{
    36→  @Override
    37→  public Object findInjectableValueId(AnnotatedMember m)
    38→  {
    39→    if (m.getAnnotation(JacksonInject.class) == null) {
    40→      return null;
    41→    }
    42→
    43→    Annotation guiceAnnotation = null;
    44→    for (Annotation annotation : m.annotations()) {
    45→      if (annotation.annotationType().isAnnotationPresent(BindingAnnotation.class)) {
    46→        guiceAnnotation = annotation;
    47→        break;
    48→      }
    49→    }
    50→
    51→    if (guiceAnnotation == null) {
    52→      if (m instanceof AnnotatedMethod) {
    53→        throw new IAE("Annotated methods don't work very well yet...");
    54→      }
    55→      return Key.get(m.getGenericType());
    56→    }
    57→    return Key.get(m.getGenericType(), guiceAnnotation);
    58→  }
    59→}
